import{_ as i,o as r,c as t,ae as o}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Typed Adapter Interface, Registry, and Lifecycle","description":"","frontmatter":{"work_package_id":"WP01","title":"Typed Adapter Interface, Registry, and Lifecycle","lane":"done","dependencies":[],"base_branch":"main","base_commit":"039b7751197f03069c47b149a88e5886d7562a69","created_at":"2026-03-01T13:29:56.110114+00:00","subtasks":["T001","T002","T003","T004","T005"],"phase":"Phase 0 - Foundation","assignee":"","agent":"claude-haiku","shell_pid":"55629","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP01-typed-adapter-interface-registry-and-lifecycle.md","filePath":"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP01-typed-adapter-interface-registry-and-lifecycle.md"}'),a={name:"specs/025-provider-adapter-interface-and-lifecycle/tasks/WP01-typed-adapter-interface-registry-and-lifecycle.md"};function l(s,e,c,n,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="work-package-prompt-wp01-typed-adapter-interface-registry-and-lifecycle" tabindex="-1">Work Package Prompt: WP01 - Typed Adapter Interface, Registry, and Lifecycle <a class="header-anchor" href="#work-package-prompt-wp01-typed-adapter-interface-registry-and-lifecycle" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Typed Adapter Interface, Registry, and Lifecycle&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Define a typed <code>ProviderAdapter</code> interface with init, health, execute, and terminate lifecycle methods.</li><li>Implement a provider registry with configuration validation, credential binding, and concurrency limit enforcement.</li><li>Deliver a normalized error taxonomy that maps all provider error types to common codes with retryable flags.</li><li>Establish process-level isolation primitives that bind providers to lanes so failures isolate to the affected lane.</li></ul><p>Success criteria:</p><ul><li>A mock provider can register, pass health checks, execute tasks, and terminate through the typed interface.</li><li>Invalid configuration is rejected with a normalized error before any provider process is spawned.</li><li>Process isolation wrapper prevents cross-lane resource leakage in tests.</li><li>All error codes across provider types map to the normalized taxonomy with zero unmapped codes.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/025-provider-adapter-interface-and-lifecycle/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/025-provider-adapter-interface-and-lifecycle/spec.md</code></li><li>Existing protocol code: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/bus.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/protocol/types.ts</code></li></ul></li></ul><p>Constraints:</p><ul><li>TypeScript + Bun runtime.</li><li>Process-level isolation via OS child processes, not in-process sandboxing.</li><li>Adapter overhead &lt; 10ms (p95); init &lt; 5s (p95).</li><li>Files target &lt;=350 lines, hard limit &lt;=500.</li><li>Fail-fast behavior; no silent fallback.</li><li>Coverage &gt;=85% with FR-025-* traceability.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-define-provideradapter-typed-interface" tabindex="-1">Subtask T001 - Define ProviderAdapter typed interface <a class="header-anchor" href="#subtask-t001-define-provideradapter-typed-interface" aria-label="Permalink to &quot;Subtask T001 - Define ProviderAdapter typed interface&quot;">​</a></h3><ul><li>Purpose: Establish the contract all providers (ACP, MCP, A2A) must implement.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/adapter.ts</code>.</li><li>Define <code>ProviderAdapter&lt;TConfig, TExecuteInput, TExecuteOutput&gt;</code> interface with generic type parameters for protocol-specific extensibility.</li><li>Define lifecycle methods: <ul><li><code>init(config: TConfig): Promise&lt;void&gt;</code> -- initialize provider with validated config, must complete within 5s or throw timeout error.</li><li><code>health(): Promise&lt;ProviderHealthStatus&gt;</code> -- return current health state (healthy, degraded, unavailable) with failure count and last-check timestamp.</li><li><code>execute(input: TExecuteInput, correlationId: string): Promise&lt;TExecuteOutput&gt;</code> -- execute a task with mandatory correlation ID propagation.</li><li><code>terminate(): Promise&lt;void&gt;</code> -- graceful shutdown, release all resources (child processes, FDs, memory).</li></ul></li><li>Define <code>ProviderHealthStatus</code> type with fields: <code>state: &#39;healthy&#39; | &#39;degraded&#39; | &#39;unavailable&#39;</code>, <code>lastCheck: Date</code>, <code>failureCount: number</code>, <code>message?: string</code>.</li><li>Define <code>ProviderRegistration&lt;TConfig&gt;</code> type with fields: <code>id: string</code>, <code>type: &#39;acp&#39; | &#39;mcp&#39; | &#39;a2a&#39;</code>, <code>config: TConfig</code>, <code>workspaceId: string</code>, <code>concurrencyLimit: number</code>, <code>healthCheckIntervalMs: number</code>.</li><li>Export all types and the interface.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/adapter.ts</code></li></ul></li><li>Validation: <ul><li>TypeScript compilation passes with strict mode.</li><li>Interface is usable by a mock implementation in tests.</li><li>Generic type parameters allow ACP, MCP, and A2A to specialize without type casts.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-provider-registry-with-configuration-validation" tabindex="-1">Subtask T002 - Implement provider registry with configuration validation <a class="header-anchor" href="#subtask-t002-implement-provider-registry-with-configuration-validation" aria-label="Permalink to &quot;Subtask T002 - Implement provider registry with configuration validation&quot;">​</a></h3><ul><li>Purpose: Manage provider registrations with validation, credential binding, and lifecycle tracking.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/registry.ts</code>.</li><li>Implement <code>ProviderRegistry</code> class with: <ul><li><code>register(registration: ProviderRegistration): Promise&lt;void&gt;</code> -- validate config schema, bind credentials (delegate to spec 028 store interface or stub), call <code>adapter.init()</code>, add to active registry.</li><li><code>unregister(providerId: string): Promise&lt;void&gt;</code> -- call <code>adapter.terminate()</code>, remove from registry, clean up credential bindings.</li><li><code>get(providerId: string): ProviderAdapter | undefined</code> -- retrieve active adapter by ID.</li><li><code>listByType(type: &#39;acp&#39; | &#39;mcp&#39; | &#39;a2a&#39;): ProviderAdapter[]</code> -- list active adapters by protocol type.</li><li><code>listByWorkspace(workspaceId: string): ProviderAdapter[]</code> -- list adapters bound to a workspace.</li></ul></li><li>Implement configuration validation: <ul><li>Reject registrations with missing required fields.</li><li>Reject registrations with concurrency limits &lt; 1 or &gt; 100.</li><li>Reject registrations with health check intervals &lt; 5000ms.</li></ul></li><li>Implement concurrency tracking per provider: <ul><li>Track in-flight execute calls.</li><li>Reject execute calls that exceed the configured concurrency limit with a normalized error.</li></ul></li><li>Emit lifecycle events on the protocol bus: <code>provider.registered</code>, <code>provider.unregistered</code>, <code>provider.init.failed</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/registry.ts</code></li></ul></li><li>Validation: <ul><li>Registry accepts valid registrations and rejects invalid ones with specific error codes.</li><li>Concurrency limits are enforced under load.</li><li>Bus events are emitted for all lifecycle transitions.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-normalized-error-taxonomy" tabindex="-1">Subtask T003 - Implement normalized error taxonomy <a class="header-anchor" href="#subtask-t003-implement-normalized-error-taxonomy" aria-label="Permalink to &quot;Subtask T003 - Implement normalized error taxonomy&quot;">​</a></h3><ul><li>Purpose: Map all provider error types (ACP, MCP, A2A, internal) to a common error code system.</li><li>Steps: <ol><li>Create <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/errors.ts</code>.</li><li>Define <code>NormalizedProviderError</code> class extending <code>Error</code> with fields: <ul><li><code>code: string</code> -- e.g., <code>PROVIDER_INIT_FAILED</code>, <code>PROVIDER_TIMEOUT</code>, <code>PROVIDER_CRASHED</code>, <code>PROVIDER_POLICY_DENIED</code>, <code>PROVIDER_CONCURRENCY_EXCEEDED</code>, <code>PROVIDER_UNAVAILABLE</code>, <code>PROVIDER_EXECUTE_FAILED</code>, <code>PROVIDER_UNKNOWN</code>.</li><li><code>providerSource: &#39;acp&#39; | &#39;mcp&#39; | &#39;a2a&#39; | &#39;internal&#39;</code>.</li><li><code>retryable: boolean</code>.</li><li><code>correlationId?: string</code>.</li><li><code>originalError?: Error</code>.</li></ul></li><li>Define error code enum or const object with all recognized codes and their default retryable status.</li><li>Implement <code>normalizeError(error: unknown, source: string, correlationId?: string): NormalizedProviderError</code> factory function.</li><li>Implement <code>isRetryable(error: NormalizedProviderError): boolean</code> helper.</li><li>Ensure every error code has a human-readable message template.</li><li>Add JSDoc documentation for each error code explaining when it is used.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/errors.ts</code></li></ul></li><li>Validation: <ul><li>All known error scenarios map to a specific code (no <code>UNKNOWN</code> fallthrough for expected cases).</li><li><code>normalizeError</code> handles null, undefined, string, Error, and custom error inputs.</li><li>Every error code is documented.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-process-level-isolation-wrapper" tabindex="-1">Subtask T004 - Implement process-level isolation wrapper <a class="header-anchor" href="#subtask-t004-implement-process-level-isolation-wrapper" aria-label="Permalink to &quot;Subtask T004 - Implement process-level isolation wrapper&quot;">​</a></h3><ul><li>Purpose: Ensure provider execution runs in child processes scoped to lanes, preventing cross-lane resource leaks on crash.</li><li>Steps: <ol><li>Add process isolation utilities to <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/adapter.ts</code> or a new <code>isolation.ts</code> file.</li><li>Implement <code>IsolatedProviderHost</code> class that: <ul><li>Spawns a child process per provider-lane binding using Bun&#39;s <code>spawn</code> API.</li><li>Forwards init/health/execute/terminate calls to the child process via IPC (structured clone or JSON serialization).</li><li>Monitors child process health via heartbeat messages.</li><li>Detects child process crash (exit code != 0, signal kills) and reports via normalized error.</li><li>Cleans up child process resources (kill, wait, close IPC channels) on terminate or crash.</li></ul></li><li>Implement resource leak detection: <ul><li>Track child process PIDs.</li><li>On terminate, verify no orphan child processes remain.</li><li>Log warning if cleanup takes &gt; 1s.</li></ul></li><li>Bind isolation host to lane ID so that lane termination triggers provider terminate for all providers in that lane.</li><li>Ensure provider crash in one lane does not affect providers in other lanes.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/adapter.ts</code> (or new <code>isolation.ts</code>)</li></ul></li><li>Validation: <ul><li>Child process spawn and IPC communication work end-to-end.</li><li>Crash in child process produces normalized error without host process impact.</li><li>No orphan processes after terminate.</li><li>Lane-scoped isolation verified by running two providers in different lanes and crashing one.</li></ul></li><li>Parallel: Yes (after T001/T002 are stable).</li></ul><h3 id="subtask-t005-add-unit-tests-for-adapter-registry-and-error-normalization" tabindex="-1">Subtask T005 - Add unit tests for adapter, registry, and error normalization <a class="header-anchor" href="#subtask-t005-add-unit-tests-for-adapter-registry-and-error-normalization" aria-label="Permalink to &quot;Subtask T005 - Add unit tests for adapter, registry, and error normalization&quot;">​</a></h3><ul><li>Purpose: Lock interface contracts and error behavior before protocol-specific adapters are built.</li><li>Steps: <ol><li>Create test directory <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/</code>.</li><li>Add <code>adapter.test.ts</code>: <ul><li>Test that a mock provider implementing <code>ProviderAdapter</code> compiles and can be used through the interface.</li><li>Test generic type parameter specialization for different config/input/output types.</li><li>Test that lifecycle methods are callable in expected order.</li></ul></li><li>Add <code>registry.test.ts</code>: <ul><li>Test successful registration with valid config.</li><li>Test rejection of invalid config (missing fields, bad concurrency limits, bad health intervals).</li><li>Test concurrency limit enforcement (exceed limit, verify rejection with correct error code).</li><li>Test unregister calls terminate and removes from registry.</li><li>Test bus event emission for lifecycle transitions.</li><li>Test listByType and listByWorkspace filtering.</li></ul></li><li>Add <code>errors.test.ts</code>: <ul><li>Test <code>normalizeError</code> with null, undefined, string, Error, and custom error inputs.</li><li>Test every error code maps to correct retryable status.</li><li>Test that no expected error scenario falls through to <code>PROVIDER_UNKNOWN</code>.</li><li>Test human-readable message generation for each code.</li></ul></li><li>Add <code>isolation.test.ts</code>: <ul><li>Test child process spawn and IPC round-trip.</li><li>Test crash detection and normalized error reporting.</li><li>Test cleanup on terminate (no orphan processes).</li></ul></li><li>Ensure all tests run via <code>bun test</code> or Vitest.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/adapter.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/registry.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/errors.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/providers/__tests__/isolation.test.ts</code></li></ul></li><li>Validation: <ul><li>All tests pass.</li><li>Coverage &gt;=85% on adapter.ts, registry.ts, errors.ts.</li><li>Each FR-025-001, FR-025-002, FR-025-007, FR-025-008, FR-025-011 has at least one mapped test.</li></ul></li><li>Parallel: Yes (after T001/T002/T003 are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Run unit tests via Bun/Vitest.</li><li>Mock providers implement <code>ProviderAdapter</code> interface with configurable behavior (success, failure, timeout, crash).</li><li>Process isolation tests use real child processes with mock provider logic.</li><li>Coverage gate: &gt;=85% on all files in <code>apps/runtime/src/providers/</code>.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: Generic type parameters too complex for downstream adapters.</li><li>Mitigation: Provide concrete type aliases for ACP, MCP, A2A configurations in adapter.ts.</li><li>Risk: Child process IPC serialization overhead exceeds 10ms budget.</li><li>Mitigation: Benchmark IPC round-trip in T005 isolation tests; switch to shared memory if needed.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm <code>ProviderAdapter</code> interface supports all three protocol types without type casts.</li><li>Confirm registry rejects all invalid configurations with specific error codes.</li><li>Confirm normalized error taxonomy covers all expected failure modes.</li><li>Confirm process isolation prevents cross-lane resource leakage.</li><li>Confirm no silent fallback or ignore paths in any validation.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:29:56Z – claude-haiku – shell_pid=55629 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:33:13Z – claude-haiku – shell_pid=55629 – lane=done – Implemented: All 5 subtasks complete</li></ul>',30)])])}const m=i(a,[["render",l]]);export{h as __pageData,m as default};
